let cciSelected=null,cciMeta=null,cciCompare=new Set(),cciEpoch=0;
const cciApi=(action,data={})=>workspaceApi('cci/'+action,data);
function cciShell(){return heading('Curriculum & Course Intelligence','Scholarion Academy · Draft, align, review and improve')+`<section class="card prose"><p><strong>AI DRAFT — REQUIRES HUMAN EDUCATOR REVIEW</strong></p><p>Ten-week courses · Non-credit certificates · No external institution connection</p><label>Authorized course <select id="cci-course"></select></label><p id="cci-status" role="status"></p><button class="button secondary" id="cci-refresh">Refresh drafts</button><a class="button secondary" href="#curriculum-review">Full course package validator</a></section><section class="card prose"><h2>Design studio</h2><p>Create a structured local scaffold. This does not generate finished lessons, executed labs or verified question banks.</p><form id="cci-create"><label>Design type<select name="kind"><option value="course">Ten-week course</option><option value="program">Non-credit program</option></select></label><label>Title<input name="title" required maxlength="250"></label><label>Target audience<input name="audience" required maxlength="500"></label><button class="button">Create draft</button></form></section><section class="card prose"><h2>Use an existing course package</h2><p>Convert a structurally valid package already saved in Curriculum validation into a graph draft. No external import occurs.</p><form id="cci-import"><label>Saved review<select name="review" id="cci-reviews" required></select></label><button class="button secondary">Create graph from review</button></form></section><section><h2>Curriculum library</h2><button class="button secondary" id="cci-compare">Compare selected drafts (up to 3)</button><div class="cci-grid" id="cci-library"></div></section><div id="cci-detail"></div><section class="card prose"><h2>Curriculum Exchange</h2><p>Transfer is disabled. Sections 5 and 6 of the supplied specification are missing. Source-owner and destination-owner approvals, licenses and branding decisions must be defined before exchanging any package. No external institution identities, grades, enrollments or database connections are imported.</p></section>`;}
async function cciLoad(){
 const epoch=++cciEpoch;workspaceSession=await workspaceApi('session');
 if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';
 const data=await cciApi('list');if(epoch!==cciEpoch||location.hash!=='#curriculum-intelligence')return;cciMeta=data;normalizeWorkspace();const reviews=await workspaceApi('curriculum/history');if(epoch!==cciEpoch||location.hash!=='#curriculum-intelligence')return;document.getElementById('cci-reviews').innerHTML='<option value="">Choose a saved package</option>'+reviews.map(r=>`<option value="${esc(r.id)}">${esc(new Date(r.created*1000).toLocaleString())} � ${JSON.parse(r.validation).length} structural findings</option>`).join('');
 document.getElementById('cci-course').innerHTML=workspaceSession.courses.map(c=>`<option value="${esc(c)}" ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('');
 document.getElementById('cci-library').innerHTML=data.drafts.map(d=>`<article class="card prose cci-card"><img src="assets/scholarion-logo.png" alt="Scholarion Academy" width="210"><label><input type="checkbox" data-cci-compare="${esc(d.id)}" ${cciCompare.has(d.id)?'checked':''}> Compare</label><p class="eyebrow">NON-CREDIT · ${esc(d.state.replaceAll('_',' '))}</p><h3>${esc(d.title)}</h3><p>Version ${esc(d.version)} · Revision ${d.revision}</p><p>AI draft · Review evidence required</p><button class="button" data-cci-open="${esc(d.id)}">View curriculum</button></article>`).join('')||'<section class="card prose"><p>No curriculum drafts in this course yet. Create one above to begin.</p></section>';
 document.getElementById('cci-status').textContent='Loaded authorized course drafts. Publication remains blocked.';
}
function cciDetail(){
 const d=cciSelected,g=d.graph,e=d.evidence;
 const options=g.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.type+': '+n.title)}</option>`).join('');
 document.getElementById('cci-detail').innerHTML=`<section class="card prose"><h2>${esc(d.title)}</h2><p>${esc(d.state)} · ${esc(d.version)} · ${g.nodes.length} nodes · ${g.edges.length} links</p><p>${esc(d.note)}</p><div class="row"><button class="button secondary" id="cci-export">Download saved evidence pack</button>${['draft','changes_requested'].includes(d.state)?'<button class="button" id="cci-propose">Submit for review</button>':''}</div><h3>Saved-version alignment and quality evidence</h3><p>These checks identify evidence gaps; they do not establish accreditation, accessibility conformance or academic approval.</p><ul>${e.findings.map(f=>`<li><b>${esc(f.code)}</b> · ${esc(f.node)}: ${esc(f.reason)} <small>Source: ${esc(f.source)} · ${esc(f.confidence)}</small></li>`).join('')||'<li>No findings from the limited metadata rules. Human review is still required.</li>'}</ul><h3>Graph nodes</h3><div class="table-wrap"><table><thead><tr><th>Type</th><th>Title</th><th>Identifier</th></tr></thead><tbody>${g.nodes.map(n=>`<tr><td>${esc(n.type)}</td><td>${esc(n.title)}</td><td>${esc(n.id)}</td></tr>`).join('')}</tbody></table></div><h3>Add a node</h3><form id="cci-node"><label>Type<select name="type">${cciMeta.nodeTypes.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Title<input name="title" required maxlength="250"></label><label>Description<textarea name="description" maxlength="6000"></textarea></label><button class="button secondary">Add to working draft</button></form><h3>Add an alignment link</h3><form id="cci-edge"><label>From<select name="from">${options}</select></label><label>Relationship<select name="type">${cciMeta.edgeTypes.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>To<select name="to">${options}</select></label><button class="button secondary">Add link</button></form><h3>Save a new version</h3><form id="cci-save"><label>Next semantic version<input name="version" required pattern="[0-9]+\.[0-9]+\.[0-9]+" placeholder="0.2.0"></label><label>Change summary<textarea name="note" required maxlength="1000"></textarea></label><details><summary>Advanced graph editor</summary><label>Curriculum nodes and links JSON<textarea id="cci-json" name="graph" rows="12">${esc(JSON.stringify(g,null,2))}</textarea></label></details><button class="button">Save versioned draft</button></form>${d.state==='in_review'?'<h3>Independent educator review</h3><form id="cci-review"><label>Decision<select name="decision"><option value="changes_requested">Request changes</option><option value="reviewed">Record review completed (not release approval)</option></select></label><label>Review evidence and reasons<textarea name="note" required maxlength="1000"></textarea></label><button class="button">Record review</button></form>':''}<h3>Immutable history</h3><ol>${d.history.map(h=>`<li>${esc(h.version)} · ${esc(h.state)} · ${esc(h.author)} — ${esc(h.note)}</li>`).join('')}</ol></section>`;
}
async function cciOpen(id){cciSelected=await cciApi('get',{id});if(location.hash==='#curriculum-intelligence')cciDetail();}
const beforeCCI=render;render=function(){if(location.hash!=='#curriculum-intelligence')return beforeCCI();document.getElementById('app').innerHTML=integratedShell('curriculum-intelligence',cciShell(),model.role);bind();normalizeWorkspace();cciLoad().catch(err=>{const target=document.getElementById('cci-status');if(target)target.textContent=err.message+' — Connect through Workspace account with an authorized instructor identity.';});};
document.addEventListener('change',e=>{if(e.target.id==='cci-course'){selectedCourse=e.target.value;cciSelected=null;cciCompare.clear();render();}if(e.target.dataset.cciCompare){const id=e.target.dataset.cciCompare;if(e.target.checked){if(cciCompare.size===3){e.target.checked=false;return;}cciCompare.add(id);}else cciCompare.delete(id);}});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['cci-import','cci-create','cci-node','cci-edge','cci-save','cci-review'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));const button=f.querySelector('button');button.disabled=true;
 try{
  if(f.id==='cci-import'){const result=await cciApi('from_review',data);await cciLoad();await cciOpen(result.id);}
  else if(f.id==='cci-create'){const result=await cciApi('create',data);await cciLoad();await cciOpen(result.id);f.reset();}
  else if(['cci-node','cci-edge'].includes(f.id)){
   const g=JSON.parse(document.getElementById('cci-json').value);
   if(f.id==='cci-node')g.nodes.push({id:crypto.randomUUID(),type:data.type,title:data.title,attributes:{description:data.description,...(data.type==='course'?{weeks:10}:{})}});else g.edges.push(data);
   cciSelected.graph=g;cciDetail();document.getElementById('cci-status').textContent='Working draft changed. Save a new version to persist it and rerun checks.';
  }else{await cciApi(f.id==='cci-save'?'save':'review',{...data,graph:f.id==='cci-save'?JSON.parse(data.graph):undefined,id:cciSelected.id,revision:cciSelected.revision});await cciLoad();await cciOpen(cciSelected.id);}
 }catch(error){document.getElementById('cci-status').textContent=error.message;}finally{button.disabled=false;}
});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-cci-open],#cci-refresh,#cci-export,#cci-propose,#cci-compare');if(!b)return;
 try{
  if(b.dataset.cciOpen)await cciOpen(b.dataset.cciOpen);
  else if(b.id==='cci-refresh')await cciLoad();
  else if(b.id==='cci-propose'){await cciApi('propose',{id:cciSelected.id,revision:cciSelected.revision});await cciLoad();await cciOpen(cciSelected.id);}
  else if(b.id==='cci-export'){const pack=await cciApi('evidence',{id:cciSelected.id});const url=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='scholarion-curriculum-evidence-'+pack.version+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  else{const packs=await Promise.all([...cciCompare].map(id=>cciApi('get',{id})));modal('Curriculum comparison',packs.length?`<div class="cci-grid">${packs.map(p=>`<article><h3>${esc(p.title)}</h3><p>${esc(p.version)} · ${esc(p.state)}</p><p>${p.graph.nodes.filter(n=>n.type==='outcome').length} outcomes · ${p.graph.nodes.filter(n=>n.type==='assessment').length} assessments</p><p>${p.evidence.findings.length} evidence gaps</p><p>Non-credit · AI draft</p></article>`).join('')}</div>`:'Select two or three curriculum cards.');}
 }catch(error){document.getElementById('cci-status').textContent=error.message;}
});
render();
